function makeJobId() {
  return `job_${Date.now()}_${Math.random().toString(36).slice(2, 10)}`;
}

function normalizeBackendBase(value) {
  return String(value || BACKEND_BASE_DEFAULT).trim().replace(/\/+$/, "");
}

function backendUrl(base, path) {
  return `${normalizeBackendBase(base)}${path}`;
}

function getErrorMessage(error, fallback) {
  if (!error) return fallback;
  if (typeof error === 'object') {
    return error.message || error.error || JSON.stringify(error);
  }
  return String(error);
}

function getUnifiedConfig() {
  return new Promise(resolve => {
    chrome.storage.local.get([
      "backendBaseUrl",
      "extensionPushToken",
      "extensionWorkerId",
      "extensionWorkerName",
      "trialCountry",
      "trialProxyMode"
    ], (data) => {
      resolve({
        backendBaseUrl: normalizeBackendBase(data.backendBaseUrl),
        extensionPushToken: String(data.extensionPushToken || EXTENSION_PUSH_TOKEN_DEFAULT).trim(),
        extensionWorkerId: String(data.extensionWorkerId || EXTENSION_WORKER_ID_DEFAULT).trim(),
        extensionWorkerName: String(data.extensionWorkerName || "").trim(),
        trialCountry: String(data.trialCountry || "ID").trim().toUpperCase(),
        trialProxyMode: String(data.trialProxyMode || "default").trim() || "default"
      });
    });
  });
}

function generateDotVariants(email) {
  const [user, domain] = email.split('@');
  if (domain.toLowerCase() !== 'gmail.com') return [email];
  const name = user.replace(/\./g, '');
  const len = name.length;
  const variants = [];
  for (let i = 0; i < 30; i++) {
    let variant = "";
    for (let j = 0; j < len - 1; j++) {
      variant += name[j];
      if (Math.random() > 0.8) variant += ".";
    }
    variant += name[len - 1];
    const full = variant + "@gmail.com";
    if (!variants.includes(full)) variants.push(full);
  }
  return variants;
}

