async function rotateProxy(url) {
  if (!url) return;
  console.log("[Proxy] Rotating IP...");
  try {
    const r = await fetchWithTimeout(url, { timeout: 10000 });
    const d = await r.json();
    // Wait a bit for IP to actually change on server side
    await new Promise(r => setTimeout(r, 2000));
    return d;
  } catch (e) {
    console.error("[Proxy] Rotate error:", e);
  }
}

