chrome.action.onClicked.addListener((tab) => {
  chrome.sidePanel.open({ windowId: tab.windowId });
});

// State management per tab
let jobs = new Map();
const CHATGPT_SECURITY_URL = "https://chatgpt.com/#settings/Security";
const PUSH_LOGOUT_TIMEOUT_MS = 75000;
const LOGOUT_POST_LOAD_SETTLE_MS = 5000;

function stripPayLinkFromJob(job) {
  if (job && typeof job === "object") {
    delete job.checkoutUrl;
    delete job.payUrl;
    delete job.paymentUrl;
  }
  return job;
}

// Load jobs from storage on startup
chrome.storage.local.get("active_jobs", (res) => {
  if (res.active_jobs) {
    let changed = false;
    jobs = new Map(Object.entries(res.active_jobs).map(([k, v]) => {
      if (v && typeof v === "object" && ("checkoutUrl" in v || "payUrl" in v || "paymentUrl" in v)) {
        changed = true;
      }
      return [Number(k), stripPayLinkFromJob(v)];
    }));
    if (changed) saveJobs();
  }
});

function saveJobs() {
  for (const job of jobs.values()) stripPayLinkFromJob(job);
  chrome.storage.local.set({ active_jobs: Object.fromEntries(jobs) });
}

function setStartupLog(text) {
  const cleanText = cleanVisibleText(text);
  chrome.storage.local.set({
    startup_log: `[${new Date().toLocaleTimeString()}] ${cleanText}`
  });
  try {
    chrome.runtime.sendMessage({ type: "STARTUP_LOG", text: cleanText });
  } catch (e) { }
}

function getJob(tabId) { return jobs.get(tabId); }
function setJob(tabId, job) {
  jobs.set(tabId, stripPayLinkFromJob(job));
  saveJobs();
}
const ACCOUNT_MODE_PLUS_TRIAL = "plus_trial";
const ACCOUNT_MODE_GPT_FREE = "gpt_free";
const FREE_BATCH_MAX = 500;

function normalizeAccountMode(value) {
  const mode = String(value || "").trim().toLowerCase();
  return ["gpt_free", "free", "chatgpt_free"].includes(mode)
    ? ACCOUNT_MODE_GPT_FREE
    : ACCOUNT_MODE_PLUS_TRIAL;
}
function isGptFreeJob(job) {
  return normalizeAccountMode(job?.accountMode) === ACCOUNT_MODE_GPT_FREE;
}
function normalizeFreeBatchTarget(value) {
  const number = Math.floor(Number(value));
  if (!Number.isFinite(number) || number < 1) return 1;
  return Math.min(number, FREE_BATCH_MAX);
}
function normalizeFreeBatchDone(value) {
  const number = Math.floor(Number(value));
  if (!Number.isFinite(number) || number < 0) return 0;
  return Math.min(number, FREE_BATCH_MAX);
}
function normalizeFreeTargetShelf(value) {
  return String(value || "").trim().toLowerCase() === "cheap" ? "cheap" : "none";
}
function setFreeBatchStorage(patch) {
  return new Promise(resolve => chrome.storage.local.set(patch, resolve));
}
function getFreeBatchStorage() {
  return new Promise(resolve => {
    chrome.storage.local.get([
      "accountMode",
      "freeBatchActive",
      "freeBatchTarget",
      "freeBatchDone",
      "freeTargetShelf",
      "lastPassword",
      "lastMailSite",
      "lastAutoPassword",
      "proxyString",
      "rotateUrl"
    ], resolve);
  });
}
async function clearFreeBatchRunState() {
  await setFreeBatchStorage({
    freeBatchActive: false,
    freeBatchDone: 0
  });
}
async function queueNextFreeBatchJob(job, done, target, logTabId = 0) {
  try {
    await delay(500);
    const stored = await getFreeBatchStorage();
    if (!stored.freeBatchActive || normalizeAccountMode(stored.accountMode) !== ACCOUNT_MODE_GPT_FREE) {
      return { success: false, skipped: true, error: "Free batch is no longer active." };
    }
    if (job?.jobId && !Array.from(jobs.values()).some(activeJob => activeJob?.jobId === job.jobId)) {
      return { success: false, skipped: true, error: "Current Free batch job was stopped." };
    }
    const autoPassword = !!(job?.autoPassword || stored.lastAutoPassword);
    const restartPassword = autoPassword
      ? generateStrongPassword()
      : String(job?.password || stored.lastPassword || "");
    const mailSite = job?.mailSource || job?.mailSite || stored.lastMailSite || "hotmail_backend";

    const result = await doStartJob(
      restartPassword,
      mailSite,
      !!job?.autoRestart,
      job?.proxyString || stored.proxyString || "",
      job?.rotateUrl || stored.rotateUrl || "",
      {
        autoPassword,
        accountMode: ACCOUNT_MODE_GPT_FREE,
        freeBatchTarget: target,
        freeBatchDone: done,
        freeBatchActive: true,
        freeTargetShelf: job?.freeTargetShelf || stored.freeTargetShelf || "none"
      }
    );
    if (!result?.success) {
      throw new Error(result?.error || "Khong start duoc acc tiep theo.");
    }
    addLog(logTabId || job?.tabId, "Da start acc tiep theo.");
    setStartupLog("Da start acc tiep theo.");
    chrome.runtime.sendMessage({ type: "LOG_UPDATE" }).catch(() => { });
    return result;
  } catch (err) {
    const errorText = err.message || String(err);
    await setFreeBatchStorage({
      freeBatchActive: false,
      freeBatchDone: done
    });
    addLog(logTabId || job?.tabId, `GPT Free batch tam dung: khong start duoc acc tiep theo (${errorText}).`);
    setStartupLog(`GPT Free batch tam dung: khong start duoc acc tiep theo (${errorText}).`);
    chrome.runtime.sendMessage({ type: "LOG_UPDATE" }).catch(() => { });
    return { success: false, error: errorText };
  }
}
function clearJobTimeout(job) {
  if (!job?.timeoutTimer) return false;
  clearTimeout(job.timeoutTimer);
  job.timeoutTimer = null;
  return true;
}
function isPaymentWaitingJob(job) {
  const step = String(job?.step || "");
  return step === "await_payment" || step === "await_push" || !!job?.checkoutTabId;
}
function findJobTarget(tabId, msg = {}) {
  const ids = [
    Number(msg.tabId || 0),
    Number(msg.checkoutTabId || 0),
    Number(tabId || 0)
  ].filter(id => Number.isInteger(id) && id > 0);
  for (const id of ids) {
    const job = getJob(id);
    if (job) return { id, job };
  }
  const jobId = String(msg.jobId || "");
  for (const [id, job] of jobs.entries()) {
    if (
      (jobId && job?.jobId === jobId) ||
      ids.includes(Number(job?.tabId || 0)) ||
      ids.includes(Number(job?.checkoutTabId || 0))
    ) {
      return { id: Number(id), job };
    }
  }
  return { id: 0, job: null };
}
async function hardStopJob(targetTabId, job, reason = "Nguoi dung bam Dung han.") {
  if (!job) return;
  clearJobTimeout(job);
  if (isGptFreeJob(job)) await clearFreeBatchRunState();
  try {
    await settleHotmailForJob(job, reason);
  } catch (e) {
    console.warn("[Hotmail] settle on hard stop failed:", e);
  }
  const idsToDelete = new Set([
    Number(targetTabId || 0),
    Number(job?.tabId || 0),
    Number(job?.checkoutTabId || 0)
  ]);
  for (const [id, activeJob] of Array.from(jobs.entries())) {
    if (idsToDelete.has(Number(id)) || (job?.jobId && activeJob?.jobId === job.jobId)) {
      jobs.delete(id);
    }
  }
  saveJobs();
  for (const id of idsToDelete) {
    if (Number.isInteger(id) && id > 0) chrome.tabs.remove(id).catch(() => { });
  }
}
function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}
function updateChromeTab(tabId, updateProperties) {
  return new Promise((resolve, reject) => {
    chrome.tabs.update(tabId, updateProperties, (tab) => {
      const err = chrome.runtime.lastError;
      if (err) reject(new Error(err.message));
      else resolve(tab);
    });
  });
}
function getChromeTab(tabId) {
  return new Promise((resolve, reject) => {
    chrome.tabs.get(tabId, (tab) => {
      const err = chrome.runtime.lastError;
      if (err) reject(new Error(err.message));
      else resolve(tab);
    });
  });
}
function isLogoutNavigationError(errorText = "") {
  return /message channel is closed|extension port is moved|back\/forward cache|receiving end does not exist|could not establish connection/i.test(String(errorText || ""));
}
function isChatGptLoggedOutUrl(url = "") {
  try {
    const parsed = new URL(String(url || ""));
    if (!parsed.hostname.includes("chatgpt.com")) return false;
    const path = parsed.pathname.toLowerCase();
    return path.includes("/auth/logout") ||
      path.includes("/auth/login") ||
      path.includes("/auth/signin") ||
      path.includes("/auth/sign-in") ||
      path === "/login" ||
      path === "/signin" ||
      path === "/sign-in";
  } catch (e) {
    return /chatgpt\.com\/(auth\/logout|auth\/login|auth\/signin|auth\/sign-in|login|signin|sign-in)/i.test(String(url || ""));
  }
}
async function waitForChatGptLogoutNavigation(tabId, ms = 30000) {
  const end = Date.now() + ms;
  let lastUrl = "";
  let lastStatus = "";
  let logoutSeenAt = 0;
  let completeSeenAt = 0;
  while (Date.now() < end) {
    try {
      const tab = await getChromeTab(tabId);
      lastUrl = tab?.url || lastUrl;
      lastStatus = tab?.status || lastStatus;
      if (isChatGptLoggedOutUrl(lastUrl)) {
        if (!logoutSeenAt) logoutSeenAt = Date.now();
        if (lastStatus === "complete") {
          if (!completeSeenAt) completeSeenAt = Date.now();
        } else {
          completeSeenAt = 0;
        }
        if (completeSeenAt && Date.now() - completeSeenAt >= LOGOUT_POST_LOAD_SETTLE_MS) {
          return { success: true, href: lastUrl, status: lastStatus, logoutPageLoaded: true };
        }
      } else if (logoutSeenAt && lastStatus === "complete") {
        if (!completeSeenAt) completeSeenAt = Date.now();
        if (Date.now() - completeSeenAt >= LOGOUT_POST_LOAD_SETTLE_MS) {
          return { success: true, href: lastUrl, status: lastStatus, logoutRedirectLoaded: true };
        }
      } else {
        completeSeenAt = 0;
      }
    } catch (e) {
      return { success: true, tabClosed: true };
    }
    await delay(600);
  }
  return { success: false, href: lastUrl, status: lastStatus, logoutSeen: !!logoutSeenAt };
}
function sendTabMessageWithTimeout(tabId, message, options = {}, timeoutMs = PUSH_LOGOUT_TIMEOUT_MS) {
  return new Promise((resolve, reject) => {
    let settled = false;
    const timer = setTimeout(() => {
      if (settled) return;
      settled = true;
      reject(new Error("Timeout khi logout ChatGPT."));
    }, timeoutMs);
    chrome.tabs.sendMessage(tabId, message, options, (res) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      const err = chrome.runtime.lastError;
      if (err) reject(new Error(err.message));
      else resolve(res);
    });
  });
}
function finishPushedJob(targetTabId, job) {
  if (job?.timeoutTimer) clearTimeout(job.timeoutTimer);
  const idsToDelete = new Set([
    Number(targetTabId || 0),
    Number(job?.tabId || 0),
    Number(job?.checkoutTabId || 0)
  ]);
  for (const [id, activeJob] of Array.from(jobs.entries())) {
    if (
      idsToDelete.has(Number(id)) ||
      (job?.jobId && activeJob?.jobId === job.jobId)
    ) {
      jobs.delete(id);
    }
  }
  saveJobs();

  const tabsToClose = new Set([
    Number(job?.tabId || targetTabId || 0),
    Number(job?.checkoutTabId || 0)
  ]);
  for (const id of tabsToClose) {
    if (Number.isInteger(id) && id > 0) {
      chrome.tabs.remove(id).catch(() => { });
    }
  }
}
async function runChatGptLogoutAfterPush(targetTabId, job) {
  const chatTabId = Number(job?.tabId || targetTabId || 0);
  if (!chatTabId) throw new Error("Khong tim thay tab ChatGPT de logout.");
  addLog(targetTabId, "Push thanh cong. Dang mo ChatGPT Security de logout...");

  await updateChromeTab(chatTabId, { url: CHATGPT_SECURITY_URL, active: true });
  await delay(1500);

  let lastError = "";
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    try {
      const res = await sendTabMessageWithTimeout(
        chatTabId,
        { type: "RUN_CHATGPT_LOGOUT_AFTER_PUSH", jobId: job?.jobId || "" },
        { frameId: 0 },
        PUSH_LOGOUT_TIMEOUT_MS
      );
      if (res?.success) return res;
      lastError = res?.error || "Content script khong logout duoc ChatGPT.";
    } catch (err) {
      lastError = err.message || String(err);
      if (isLogoutNavigationError(lastError)) {
        const navResult = await waitForChatGptLogoutNavigation(chatTabId);
        if (navResult?.success) {
          return {
            success: true,
            portClosedAfterLogout: true,
            href: navResult.href || "",
            tabClosed: !!navResult.tabClosed
          };
        }
      }
    }
    if (attempt < 3) {
      addLog(targetTabId, `Logout ChatGPT chua xong, thu lai lan ${attempt + 1}/3...`);
      await updateChromeTab(chatTabId, { url: CHATGPT_SECURITY_URL, active: true }).catch(() => { });
      await delay(1500);
    }
  }
  throw new Error(lastError || "Khong logout duoc ChatGPT.");
}
async function finishPushedJobAfterLogout(targetTabId, job, data) {
  try {
    const logoutResult = await runChatGptLogoutAfterPush(targetTabId, job);
    Object.assign(job, {
      pushed: true,
      logoutPending: false,
      logoutCompleted: true,
      logoutCompletedAt: Date.now(),
      logoutError: "",
      step: "pushed"
    });
    addLog(targetTabId, `Da logout ChatGPT va ket thuc job: ${job.email || ""}`.trim());
    let freeBatch = null;
    if (isGptFreeJob(job)) {
      const target = normalizeFreeBatchTarget(job.freeBatchTarget);
      const done = Math.min(normalizeFreeBatchDone(job.freeBatchDone) + 1, target);
      const continueBatch = !!job.freeBatchActive && done < target;
      freeBatch = { done, target, continueBatch };
      await setFreeBatchStorage({
        accountMode: ACCOUNT_MODE_GPT_FREE,
        freeBatchTarget: target,
        freeBatchDone: done,
        freeBatchActive: continueBatch,
        freeTargetShelf: normalizeFreeTargetShelf(job.freeTargetShelf)
      });
      addLog(targetTabId, continueBatch
        ? `GPT Free batch: da push ${done}/${target}. Dang start acc tiep theo...`
        : `GPT Free batch xong: da push ${done}/${target}.`);
    }
    let nextBatchStart = null;
    if (freeBatch?.continueBatch) {
      nextBatchStart = await queueNextFreeBatchJob(job, freeBatch.done, freeBatch.target, targetTabId);
      freeBatch.nextStart = nextBatchStart;
    }
    finishPushedJob(targetTabId, job);
    return { success: true, data, released: true, email: job.email, logoutResult, freeBatch };
  } catch (err) {
    const errorText = err.message || String(err);
    Object.assign(job, {
      pushed: true,
      logoutPending: true,
      logoutFailedAt: Date.now(),
      logoutError: errorText,
      step: "logout_pending"
    });
    addLog(targetTabId, `Push da thanh cong nhung logout ChatGPT loi: ${errorText}`);
    setJob(targetTabId, job);
    return {
      success: false,
      pushed: true,
      logoutPending: true,
      email: job.email,
      error: `Push thanh cong nhung logout ChatGPT loi: ${errorText}`
    };
  }
}
