function randomInt(max) {
  if (!Number.isFinite(max) || max <= 0) return 0;
  const buf = new Uint32Array(1);
  crypto.getRandomValues(buf);
  return buf[0] % max;
}

function shuffleWithCrypto(chars) {
  const list = Array.from(chars);
  for (let i = list.length - 1; i > 0; i--) {
    const j = randomInt(i + 1);
    [list[i], list[j]] = [list[j], list[i]];
  }
  return list.join("");
}

function generateStrongPassword() {
  const lower = "abcdefghijkmnopqrstuvwxyz";
  const upper = "ABCDEFGHJKLMNPQRSTUVWXYZ";
  const digits = "23456789";
  const symbols = "!@#$%^&*";
  const all = lower + upper + digits + symbols;
  const length = 14 + randomInt(3);
  let value =
    lower[randomInt(lower.length)] +
    upper[randomInt(upper.length)] +
    digits[randomInt(digits.length)] +
    symbols[randomInt(symbols.length)];
  while (value.length < length) value += all[randomInt(all.length)];
  return shuffleWithCrypto(value);
}

function cleanVisibleText(text, fallback = "Đang xử lý...") {
  const raw = String(text || "");
  if (!raw.trim()) return fallback;
  if (!/[\u00c3\u00c2\u00e2ƒ€]/.test(raw)) return raw;
  const lowered = raw.toLowerCase();
  if (lowered.includes("checkout")) return "Đang xử lý checkout...";
  if (lowered.includes("hotmail")) return "Đang xử lý Hotmail...";
  if (lowered.includes("otp")) return "Đang lấy OTP...";
  if (lowered.includes("gopay")) return "Đang xử lý GoPay...";
  if (lowered.includes("timeout")) return "Quá thời gian xử lý.";
  if (lowered.includes("error") || lowered.includes("loi") || lowered.includes("fail")) return "Có lỗi trong quá trình tự động.";
  return fallback;
}
function endJob(tabId) {
  const job = jobs.get(tabId);
  if (job && job.timeoutTimer) clearTimeout(job.timeoutTimer);
  jobs.delete(tabId);
  saveJobs();
}

