async function clearSession() {
  return new Promise((resolve) => {
    chrome.browsingData.remove({
      since: 0
    }, {
      "appcache": true,
      "cache": true,
      "cookies": true,
      "indexedDB": true,
      "localStorage": true,
      "history": true
    }, () => {
      console.log("[Clear] Browsing data cleared.");
      resolve();
    });
  });
}

function saveLocal(type, line) {
  const key = type === "success" ? "list_success" : "list_fail";
  chrome.storage.local.get([key], (d) => {
    const list = d[key] || [];
    list.push(line);
    chrome.storage.local.set({ [key]: list });
  });
}

function clearCookiesLikeEx3() {
  return new Promise((resolve) => {
    chrome.cookies.getAll({}, (cookies) => {
      if (!cookies || cookies.length === 0) {
        resolve();
        return;
      }
      const toDelete = cookies.filter(c =>
        c.domain.includes("openai.com") || c.domain.includes("chatgpt.com")
      );
      if (toDelete.length === 0) {
        resolve();
        return;
      }
      let count = toDelete.length;
      toDelete.forEach((cookie) => {
        const url = "https://" + cookie.domain.replace(/^\./, "") + cookie.path;
        chrome.cookies.remove({ url, name: cookie.name }, () => {
          count--;
          if (count === 0) resolve();
        });
      });
    });
  });
}

function isPaymentSuccessUrl(url) {
  const u = String(url || "").toLowerCase();
  if (!u) return false;

  if (u.includes("chatgpt.com") && (u.includes("/payments/success") || u.includes("/success"))) {
    return true;
  }

  if (!u.includes("midtrans.com")) return false;
  if (u.includes("gopay-tokenization") || u.includes("/snap/") || u.includes("/redirection/")) {
    return false;
  }

  return u.includes("#/success") ||
    u.includes("/success") ||
    u.includes("transaction_status=settlement") ||
    u.includes("transaction_status=capture") ||
    u.includes("status_code=200");
}

