chrome.tabs.onUpdated.addListener((tabId, changeInfo, tab) => {
  const job = getJob(tabId);
  if (!job) return;

  const url = tab.url || changeInfo.url || "";

  // Success detection
  if (isPaymentSuccessUrl(url)) {
    if (job.step !== "await_push" && job.step !== "pushed") {
      job.step = "await_push";
      saveJobs();
      addLog(tabId, "Detected payment success. Payment remains manual; press Push when ready.");
      chrome.runtime.sendMessage({ type: "STATUS_UPDATE", job }).catch(() => { });
    }
  }
});

